def fail_of(n):
    t = (HERE / 'src' / ('ch%02d.md' % n)).read_text(encoding='utf-8')
    b = t.split('## 本章怎样算错', 1)[1].strip().split('\n')[0]
    b = re.sub(r'^第一条[，：:、]\s*', '', b)
    m = re.match(r'(.{30,160}?。)', b)
    return (m.group(1) if m else b[:160])
